function resolveSdkVersion(expoVersion) {
  if (!expoVersion || typeof expoVersion !== 'string') {
    return null;
  }

  const normalizedVersion = expoVersion.replace(/^[^0-9]*/, '');
  const [major, minor] = normalizedVersion.split('.');

  if (!major || !minor) {
    return null;
  }

  return `${major}.${minor}.0`;
}

