const GITHUB_API = 'https://api.github.com';
const DEFAULT_REPO = 'ibb142/ivx-holdings-platform';
const DEFAULT_BRANCH = 'main';

// ─── Types ───────────────────────────────────────────────────────────

export interface GitHubRepoInfo {
  owner: string;
